import { createHmac } from "crypto";

// PEAK accounting API client — https://developers.peakaccount.com (API Core v1).
// Goal: auto-post a guide payout as a PEAK expense and read back its document
// number (the EXP-… ref) into PayrollStatus.peakRef.
//
// Credentials live ONLY in Railway env vars (never in code / git):
//   PEAK_CONNECT_ID, PEAK_CONNECT_KEY  developer creds from PEAK (sign + client token)
//   PEAK_USER_TOKEN                    generated by the business owner in PEAK after
//                                      consenting to connect this app (static)
//   PEAK_API_BASE_URL / PEAK_BASE_URL  API root (either var; API_BASE_URL wins).
//                                      Defaults to the UAT sandbox; set prod URL to go live
//
// Auth: HMAC-SHA1 sign a timestamp -> POST /ClientToken -> use Client-Token +
// User-Token headers on every call. Two doc ambiguities (which value is the HMAC
// secret, and the digest encoding) are env-overridable so we can match the sandbox
// on first contact without a redeploy. Nothing runs until the env is set.

// Base URL: Railway carries both PEAK_API_BASE_URL and PEAK_BASE_URL. Prefer the
// API-specific one, fall back to the original var (what this client shipped with),
// then the UAT sandbox. Either may be given as the host root or already suffixed
// with /api/v1 — normalizePeakBase() makes both resolve to the same API root, so
// the env can be set either way without a code change.
export function normalizePeakBase(raw?: string | null): string {
  const base = (raw || "https://peakengineapidev.azurewebsites.net").trim().replace(/\/+$/, "");
  return /\/api\/v\d+$/i.test(base) ? base : `${base}/api/v1`;
}

const API = normalizePeakBase(process.env.PEAK_API_BASE_URL || process.env.PEAK_BASE_URL);
// Trimmed on read, like the base URL above. A credential pasted into Railway with a
// trailing newline or a stray space is non-empty — so peakConfigured goes green — but
// signs a wrong HMAC and sends a wrong connectId, which reads as "credentials rejected"
// with no way to tell it apart from a genuinely bad key. Trimming also makes a
// whitespace-only value report as missing (red dot) instead of silently failing.
const CONNECT_ID = (process.env.PEAK_CONNECT_ID || "").trim();
const CONNECT_KEY = (process.env.PEAK_CONNECT_KEY || "").trim();
const USER_TOKEN = (process.env.PEAK_USER_TOKEN || "").trim();
const SIGN_SECRET = (process.env.PEAK_SIGN_SECRET || "connectId") === "connectKey" ? CONNECT_KEY : CONNECT_ID;
// Verified against the PEAK UAT sandbox: the Time-Signature is HMAC-SHA1(connectId,
// timestamp) hex-encoded. Overridable, but hex is the working default (base64 →
// "TimeSignature Unauthorized").
const SIG_ENC: "hex" | "base64" = process.env.PEAK_SIG_ENCODING === "base64" ? "base64" : "hex";

export const peakConfigured = !!(CONNECT_ID && CONNECT_KEY);
export const peakEnabled = !!(CONNECT_ID && CONNECT_KEY && USER_TOKEN);
export const peakBaseUrl = API;

// yyyyMMdd HHmmss in UTC — PEAK validates the timestamp against its own (UTC)
// clock, so a Bangkok +7h stamp is rejected as out-of-window ("Invalid API
// Validate Data. (TimeStamp)"). Exported (pure) so it can be unit-tested.
export function peakTimestamp(d: Date = new Date()): string {
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}`;
}

// Which required env vars are missing (NAMES only — never values). Used by the
// connection test so a misconfigured deploy says what to set, not what it holds.
export function peakMissingEnv(): string[] {
  return [
    ["PEAK_CONNECT_ID", CONNECT_ID],
    ["PEAK_CONNECT_KEY", CONNECT_KEY],
  ].filter(([, v]) => !v).map(([k]) => k as string);
}

// Last line of defence before any PEAK text reaches a log or an HTTP response:
// strip anything that matches a credential or a token we hold. PEAK's own
// resCode/resDesc never contain secrets, but this guarantees it.
export function sanitizePeakError(msg: unknown): string {
  let out = typeof msg === "string" ? msg : msg instanceof Error ? msg.message : "unknown error";
  for (const secret of [CONNECT_ID, CONNECT_KEY, USER_TOKEN, cached?.token]) {
    if (secret && secret.length >= 6) out = out.split(secret).join("[redacted]");
  }
  return out.slice(0, 300);
}

function stamp(): string {
  return peakTimestamp();
}

// PEAK responses capitalize the wrapper key (e.g. `PeakClientToken`) while requests
// send it lowercase — read either casing so a valid response is never missed.
function peakWrap<T>(j: Record<string, unknown>, key: string): T | undefined {
  const cap = key.charAt(0).toUpperCase() + key.slice(1);
  return (j[key] ?? j[cap]) as T | undefined;
}
function sigHeaders(): Record<string, string> {
  const ts = stamp();
  const sig = createHmac("sha1", SIGN_SECRET).update(ts).digest(SIG_ENC);
  return { "Time-Stamp": ts, "Time-Signature": sig };
}

type Res<T> = { ok: boolean; code?: string; desc?: string } & T;

let cached: { token: string; at: number } | null = null;

// One ClientToken attempt. PEAK's docs name the secret field `password`; this
// client shipped sending `connectKey`, which commit 076b3c0 proved the UAT
// sandbox accepts. Both carry the same PEAK_CONNECT_KEY value, so we try the
// documented name first and fall back to the proven one rather than guessing.
async function requestClientToken(field: "password" | "connectKey"): Promise<Res<{ token?: string }>> {
  let r: Response;
  try {
    r = await fetch(`${API}/ClientToken`, {
      method: "POST",
      headers: { "content-type": "application/json", ...sigHeaders() },
      body: JSON.stringify({ peakClientToken: { connectId: CONNECT_ID, [field]: CONNECT_KEY } }),
    });
  } catch (e) { return { ok: false, desc: sanitizePeakError(`network: ${(e as Error).message}`) }; }
  const j = await r.json().catch(() => ({} as Record<string, unknown>));
  const t = peakWrap<{ token?: string; resCode?: string; resDesc?: string }>(j, "peakClientToken");
  if (t?.token) return { ok: true, token: t.token, code: t.resCode, desc: t.resDesc };
  // Non-2xx, or a 200 carrying PEAK's own error code: surface the code/description
  // only — never the raw body (it echoes the request) and never the credentials.
  return { ok: false, code: t?.resCode, desc: sanitizePeakError(t?.resDesc || `HTTP ${r.status}`) };
}

export async function clientToken(force = false): Promise<Res<{ token?: string }>> {
  const missing = peakMissingEnv();
  if (missing.length) return { ok: false, desc: `not configured: set ${missing.join(", ")}` };
  if (!force && cached && Date.now() - cached.at < 50 * 60_000) return { ok: true, token: cached.token };
  let res = await requestClientToken("password");
  if (!res.ok) res = await requestClientToken("connectKey");
  if (res.ok && res.token) cached = { token: res.token, at: Date.now() };
  return res;
}

async function authedHeaders(): Promise<Record<string, string> | null> {
  const ct = await clientToken();
  if (!ct.ok || !ct.token) return null;
  return { "content-type": "application/json", "Client-Token": ct.token, "User-Token": USER_TOKEN, ...sigHeaders() };
}

// One combined expense + payment (peakExpenses.expenses[] shape). Returns the
// created document `code` (the EXP-… reference).
export async function createExpenseAllInOne(expense: Record<string, unknown>): Promise<Res<{ id?: string; link?: string }>> {
  if (!peakEnabled) return { ok: false, desc: "PEAK not fully configured (need PEAK_USER_TOKEN)" };
  const headers = await authedHeaders();
  if (!headers) return { ok: false, desc: "could not obtain PEAK client token" };
  let r: Response;
  try {
    r = await fetch(`${API}/Expenses/allinone`, { method: "POST", headers, body: JSON.stringify({ peakExpenses: { expenses: [expense], getResult: 1 } }) });
  } catch (e) { return { ok: false, desc: `network: ${(e as Error).message}` }; }
  const j = await r.json().catch(() => ({} as Record<string, unknown>));
  const wrap = peakWrap<{ expenses?: Array<{ code?: string; id?: string; documentLink?: string; resCode?: string; resDesc?: string }>; resDesc?: string }>(j, "peakExpenses");
  const e = wrap?.expenses?.[0];
  if (e?.code) return { ok: true, code: e.code, id: e.id, link: e.documentLink, desc: e.resDesc };
  return { ok: false, code: e?.resCode, desc: e?.resDesc || wrap?.resDesc || `HTTP ${r.status}` };
}

// Chart of accounts (read-only) — the account code + name list an operator picks
// from when mapping FolkOPS categories. GET /api/v1/DailyJournals/accountcode per
// PEAK's API reference; response wrapper is PeakAccountCode -> accountCode[].
//
// Deliberately READ-ONLY: this cannot create or post anything. It reuses the same
// authedHeaders()/peakWrap()/sanitizePeakError() path as getContacts() below, so
// the Client Token handshake is untouched.
export type PeakAccountCode = { code: string; name: string; nameEn?: string };

// Pure parser for the chart response, exported so the shape can be unit tested —
// this call has never run against PEAK, so the parsing is the part most likely to
// be wrong and the part hardest to verify live.
//
// Returns either the accounts, or a diagnostic naming the KEYS actually present
// (never their values — the payload is business data). A 200 whose shape we
// misread would otherwise look like a working call with no accounts, which is the
// worst outcome because it is silent.
export function parsePeakAccounts(j: Record<string, unknown>): { accounts: PeakAccountCode[] } | { error: string } {
  const wrap = peakWrap<{ accountCode?: unknown; resCode?: string; resDesc?: string }>(j ?? {}, "peakAccountCode");
  const list = wrap?.accountCode;
  if (!Array.isArray(list)) {
    const topKeys = Object.keys(j ?? {}).slice(0, 8);
    const innerKeys = wrap && typeof wrap === "object" ? Object.keys(wrap).slice(0, 8) : [];
    return {
      error:
        `PEAK replied 200 but no account array was found. Response keys: [${topKeys.join(", ") || "none"}]` +
        (innerKeys.length ? `; inside the wrapper: [${innerKeys.join(", ")}]` : ""),
    };
  }
  const accounts = (list as PeakAccountCode[])
    .filter((a) => (a?.code ?? "").toString().trim())
    .map((a) => ({ code: String(a.code).trim(), name: String(a.name ?? "").trim(), nameEn: a.nameEn ? String(a.nameEn).trim() : undefined }));
  return { accounts };
}

export async function getAccountCodes(): Promise<Res<{ accounts?: PeakAccountCode[] }>> {
  if (!peakEnabled) return { ok: false, desc: "PEAK not fully configured (need PEAK_USER_TOKEN)" };
  const headers = await authedHeaders();
  if (!headers) return { ok: false, desc: "could not obtain PEAK client token" };
  let r: Response;
  try { r = await fetch(`${API}/DailyJournals/accountcode`, { method: "GET", headers }); }
  catch (e) { return { ok: false, desc: sanitizePeakError(`network: ${(e as Error).message}`) }; }
  const j = await r.json().catch(() => ({} as Record<string, unknown>));
  const wrap = peakWrap<{ resCode?: string; resDesc?: string }>(j, "peakAccountCode");
  if (!r.ok) return { ok: false, code: wrap?.resCode, desc: sanitizePeakError(wrap?.resDesc || `HTTP ${r.status}`) };
  const parsed = parsePeakAccounts(j);
  if ("error" in parsed) return { ok: false, code: wrap?.resCode, desc: sanitizePeakError(wrap?.resDesc || parsed.error) };
  return { ok: true, accounts: parsed.accounts, code: wrap?.resCode, desc: wrap?.resDesc };
}

// Payment methods (read-only) — the bank/cash accounts a payment can settle to.
// GET /api/v1/PaymentMethods, wrapper PeakPaymentMethods. PEAK's docs list the
// object's fields but not the array key inside the wrapper, so the parser accepts
// the documented naming pattern and REPORTS what it found when it cannot match —
// the same defence added after the chart call shipped unverified.
export type PeakPaymentMethod = { id: string; code?: string; name: string; type?: string; bankName?: string; accountNumber?: string };

export type PaymentMethodParse =
  | { methods: PeakPaymentMethod[]; meta: { wrapperKeys: string[]; arrayKey: string; rawCount: number; droppedNoId: number } }
  | { error: string };

export function parsePeakPaymentMethods(j: Record<string, unknown>): PaymentMethodParse {
  const wrap = peakWrap<Record<string, unknown>>(j ?? {}, "peakPaymentMethods");
  const wrapperKeys = wrap && typeof wrap === "object" ? Object.keys(wrap) : [];

  // Prefer an array whose key actually names payment methods; only then fall back
  // to "the first array present". Picking the first array blindly could latch onto
  // an unrelated collection and quietly return the wrong list.
  const arrays = wrapperKeys.filter((k) => Array.isArray((wrap as Record<string, unknown>)[k]));
  const arrayKey = arrays.find((k) => /payment|method|bank|account/i.test(k)) ?? arrays[0];

  if (!arrayKey) {
    const topKeys = Object.keys(j ?? {}).slice(0, 8);
    return {
      error: `PEAK replied 200 but no payment-method array was found. Response keys: [${topKeys.join(", ") || "none"}]` +
             (wrapperKeys.length ? `; inside the wrapper: [${wrapperKeys.slice(0, 8).join(", ")}]` : ""),
    };
  }

  const raw = ((wrap as Record<string, unknown>)[arrayKey] ?? []) as PeakPaymentMethod[];
  const methods = raw
    .filter((m) => (m?.id ?? "").toString().trim())
    .map((m) => ({
      id: String(m.id).trim(),
      code: m.code ? String(m.code).trim() : undefined,
      name: String(m.name ?? "").trim(),
      type: m.type ? String(m.type).trim() : undefined,
      bankName: m.bankName ? String(m.bankName).trim() : undefined,
      accountNumber: m.accountNumber ? String(m.accountNumber).trim() : undefined,
    }));

  // rawCount vs methods.length is the whole point: it separates "PEAK only has one
  // payment method" from "we silently dropped the others". Without it, a short list
  // is indistinguishable from a parsing bug.
  return { methods, meta: { wrapperKeys, arrayKey, rawCount: raw.length, droppedNoId: raw.length - methods.length } };
}

export async function getPaymentMethods(): Promise<Res<{ methods?: PeakPaymentMethod[]; meta?: { wrapperKeys: string[]; arrayKey: string; rawCount: number; droppedNoId: number } }>> {
  if (!peakEnabled) return { ok: false, desc: "PEAK not fully configured (need PEAK_USER_TOKEN)" };
  const headers = await authedHeaders();
  if (!headers) return { ok: false, desc: "could not obtain PEAK client token" };
  let r: Response;
  // PEAK pages at 10 entries per page by default and this call sent no params at
  // all, so a company with more than ten payment methods would silently see only
  // the first page. Ask for the lot.
  try { r = await fetch(`${API}/PaymentMethods?limit=200`, { method: "GET", headers }); }
  catch (e) { return { ok: false, desc: sanitizePeakError(`network: ${(e as Error).message}`) }; }
  const j = await r.json().catch(() => ({} as Record<string, unknown>));
  const wrap = peakWrap<{ resCode?: string; resDesc?: string }>(j, "peakPaymentMethods");
  if (!r.ok) return { ok: false, code: wrap?.resCode, desc: sanitizePeakError(wrap?.resDesc || `HTTP ${r.status}`) };
  const parsed = parsePeakPaymentMethods(j);
  if ("error" in parsed) return { ok: false, code: wrap?.resCode, desc: sanitizePeakError(wrap?.resDesc || parsed.error) };
  return { ok: true, methods: parsed.methods, meta: parsed.meta, code: wrap?.resCode, desc: wrap?.resDesc };
}

// Vendor/contact list (read-only) — the guides that already exist in PEAK, so an
// operator LINKS to one instead of pasting an opaque id.
// GET /api/v1/Contacts/list, wrapper PeakContacts -> contacts[].
//
// PEAK pages at 10 entries by default, so `limit` is always sent: a picker that
// silently showed the first ten guides would look like the rest do not exist.
export type PeakContact = { id: string; name: string; code?: string; taxNumber?: string; type?: string };

export function parsePeakContacts(j: Record<string, unknown>): { contacts: PeakContact[] } | { error: string } {
  const wrap = peakWrap<{ contacts?: unknown; resCode?: string; resDesc?: string }>(j ?? {}, "peakContacts");
  const list = wrap?.contacts;
  if (!Array.isArray(list)) {
    const topKeys = Object.keys(j ?? {}).slice(0, 8);
    const innerKeys = wrap && typeof wrap === "object" ? Object.keys(wrap).slice(0, 8) : [];
    return {
      error: `PEAK replied 200 but no contact array was found. Response keys: [${topKeys.join(", ") || "none"}]` +
             (innerKeys.length ? `; inside the wrapper: [${innerKeys.join(", ")}]` : ""),
    };
  }
  const contacts = (list as PeakContact[])
    .filter((c) => (c?.id ?? "").toString().trim())
    .map((c) => ({
      id: String(c.id).trim(),
      name: String(c.name ?? "").trim(),
      code: c.code ? String(c.code).trim() : undefined,
      taxNumber: c.taxNumber ? String(c.taxNumber).trim() : undefined,
      type: c.type != null ? String(c.type).trim() : undefined,
    }));
  return { contacts };
}

export async function getContacts(opts: { searchText?: string; limit?: number; page?: number } = {}): Promise<Res<{ contacts?: PeakContact[] }>> {
  if (!peakEnabled) return { ok: false, desc: "PEAK not fully configured (need PEAK_USER_TOKEN)" };
  const headers = await authedHeaders();
  if (!headers) return { ok: false, desc: "could not obtain PEAK client token" };
  const qs = new URLSearchParams();
  if (opts.searchText?.trim()) qs.set("searchText", opts.searchText.trim());
  qs.set("limit", String(Math.min(Math.max(opts.limit ?? 200, 1), 500)));
  if (opts.page) qs.set("page", String(opts.page));
  let r: Response;
  try { r = await fetch(`${API}/Contacts/list?${qs.toString()}`, { method: "GET", headers }); }
  catch (e) { return { ok: false, desc: sanitizePeakError(`network: ${(e as Error).message}`) }; }
  const j = await r.json().catch(() => ({} as Record<string, unknown>));
  const wrap = peakWrap<{ resCode?: string; resDesc?: string }>(j, "peakContacts");
  if (!r.ok) return { ok: false, code: wrap?.resCode, desc: sanitizePeakError(wrap?.resDesc || `HTTP ${r.status}`) };
  const parsed = parsePeakContacts(j);
  if ("error" in parsed) return { ok: false, code: wrap?.resCode, desc: sanitizePeakError(wrap?.resDesc || parsed.error) };
  return { ok: true, contacts: parsed.contacts, code: wrap?.resCode, desc: wrap?.resDesc };
}
